void Solver::bump_var(int var, double coeff) {
    // increase activity with the given coefficient
    double inc = var_inc * coeff;
    activity[var] += inc;

    // prevent overflow by scaling down all activities
    if (activity[var] > 1e100) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        // update only if the increase is noticeable to reduce heap churn
        if (inc > 1e-8) vsids.update(var);
    } else {
        // insert variables that have become active
        if (activity[var] > 0) vsids.insert(var);
    }
}
